/**
 * Dollar cost for a whole session, computed by the Cloud Agents
 * `POST /v1/models/estimate-cost` endpoint: billed usage events for the
 * conversation when they can be read, otherwise live catalog pricing of the
 * session's summed tokens.
 *
 * The billed lookup scans the owning team's usage history, so it runs only
 * when something asks for a session's cost, never once per turn.
 */
import { cursorExternalApiUrl, resolveApiKey } from "./cursor/credentials.js";
import { isRecord } from "./is-record.js";
export function modelSettingId(model) {
    return typeof model === "string" ? model : model.id;
}
/**
 * This estimate-cost client treats OpenAI-compat usage as **provider-gross**
 * (local playground: `prompt_tokens` includes `cachedPromptTokens`). Catalog
 * `costForBaseTier` assumes Anthropic / billing-style disjoint nets and ADDs
 * `cacheRead × cachedRate` on top of `input × inputRate`, so we send
 * `input − cache` for Grok / xAI / GPT / o-series.
 *
 * Non-OpenAI-compat models are left alone. `input < cache` is only a
 * defensive clamp (avoid a negative uncached count), not a detector for
 * billed / openaiProxy-shaped tokens. Cloud catalog fallback with already-
 * netted OpenAI-compat usage is out of scope here.
 */
export function isOpenAiCompatGrossCacheModel(model) {
    const id = modelSettingId(model).toLowerCase();
    return (id.includes("grok") || id.includes("xai") || id.includes("gpt") || /(^|[-_/])o[1-9]/.test(id));
}
export function toCatalogDisjointUsage(usage, model) {
    if (model === undefined || !isOpenAiCompatGrossCacheModel(model)) {
        return usage;
    }
    const cachedTokens = usage.cacheReadTokens + usage.cacheWriteTokens;
    if (cachedTokens === 0 || usage.inputTokens < cachedTokens) {
        return usage;
    }
    return {
        ...usage,
        inputTokens: usage.inputTokens - cachedTokens,
    };
}
export function roundCostUsd(usd) {
    return Math.round(usd * 1e6) / 1e6;
}
export function estimatedCostFromCents(args) {
    return {
        totalUsd: roundCostUsd(args.cost.chargedCents / 100),
        model: modelSettingId(args.model),
        source: args.source,
        rawCostCents: args.cost.rawCostCents,
        chargedCents: args.cost.chargedCents,
    };
}
/** The endpoint keeps scanning after this client gives up, so the bound only caps the caller's wait. */
const ESTIMATE_COST_TIMEOUT_MS = 5_000;
export async function estimateCostFromApi(input) {
    const resolved = await resolveApiKey();
    if (resolved === undefined) {
        return undefined;
    }
    const priced = await requestEstimate(resolved.apiKey, input);
    if (priced !== undefined) {
        return priced;
    }
    // The billed lookup can time out or miss. Catalog-price the summed usage
    // instead; omitting the ids keeps the retry from asking for billed events
    // again.
    if (input.usage === undefined) {
        return undefined;
    }
    return requestEstimate(resolved.apiKey, { model: input.model, usage: input.usage });
}
async function requestEstimate(apiKey, input) {
    const model = modelSettingId(input.model);
    const catalogUsage = input.usage === undefined ? undefined : toCatalogDisjointUsage(input.usage, input.model);
    let response;
    try {
        response = await fetch(`${cursorExternalApiUrl()}/v1/models/estimate-cost`, {
            method: "POST",
            headers: {
                authorization: `Bearer ${apiKey}`,
                "content-type": "application/json",
            },
            body: JSON.stringify({
                model,
                inputTokens: catalogUsage?.inputTokens,
                outputTokens: catalogUsage?.outputTokens,
                cacheReadTokens: catalogUsage?.cacheReadTokens,
                cacheWriteTokens: catalogUsage?.cacheWriteTokens,
                agentId: input.agentId,
                conversationId: input.conversationId,
            }),
            signal: AbortSignal.timeout(ESTIMATE_COST_TIMEOUT_MS),
        });
    }
    catch {
        return undefined;
    }
    if (!response.ok) {
        return undefined;
    }
    let parsed;
    try {
        parsed = await response.json();
    }
    catch {
        return undefined;
    }
    if (!isRecord(parsed) ||
        !isRecord(parsed.cost) ||
        typeof parsed.cost.rawCostCents !== "number" ||
        typeof parsed.cost.chargedCents !== "number") {
        return undefined;
    }
    return estimatedCostFromCents({
        model: input.model,
        cost: {
            rawCostCents: parsed.cost.rawCostCents,
            chargedCents: parsed.cost.chargedCents,
        },
        source: parsed.source === "usage" ? "usage" : "catalog",
    });
}
